// A deliberately small second consumer: non-square atlas cells, all GID flips,
// ordinary Tiled animation and a different generated SDK/module identity.
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"sort"
	"strings"

	"github.com/karty-game/tiled/assets"
	"github.com/karty-game/tiled/source"
)

func must(err error) {
	if err != nil {
		panic(err)
	}
}
func main() {
	must(os.MkdirAll("art", 0755))
	must(os.MkdirAll("levels/room", 0755))
	atlas := image.NewNRGBA(image.Rect(0, 0, 35, 26))
	for tile := range 2 {
		for y := range 24 {
			for x := range 16 {
				c := color.NRGBA{45, 157, 171, 255}
				if tile == 1 {
					c = color.NRGBA{206, 101, 77, 255}
				}
				if x < 4 && y < 6 {
					c = color.NRGBA{250, 218, 105, 255}
				}
				if x >= 12 && y >= 18 {
					c = color.NRGBA{36, 52, 74, 255}
				}
				if x == 7 || y == 11 {
					c = color.NRGBA{224, 235, 210, 255}
				}
				atlas.SetNRGBA(1+tile*17+x, 1+y, c)
			}
		}
	}
	f, e := os.Create("art/atlas.png")
	must(e)
	must(png.Encode(f, atlas))
	must(f.Close())
	m, e := source.Load(os.DirFS("."), "maps/room.tmj")
	must(e)
	images := map[string]*image.NRGBA{}
	aliases, e := assets.Import(os.DirFS("."), m, func(in assets.Input) (string, error) {
		name := fmt.Sprintf("tile-%d", len(images)+1)
		images[name] = in.Pixels
		return name, nil
	})
	must(e)
	names := make([]string, 0, len(images))
	for n := range images {
		names = append(names, n)
	}
	sort.Strings(names)
	ids := map[string]int{}
	var manifest, code strings.Builder
	manifest.WriteString("# Generated by cmd/author; map placement stays in Tiled.\ntextures = [\n")
	for i, n := range names {
		ids[n] = i + 1
		f, e = os.Create("levels/room/" + n + ".png")
		must(e)
		must(png.Encode(f, images[n]))
		must(f.Close())
		fmt.Fprintf(&manifest, "{name=%q,source=%q},\n", n, n+".png")
	}
	manifest.WriteString("]\n[level]\nname=\"levels.room\"\nkind=\"tiled\"\n")
	code.WriteString("// Code generated by cmd/author. DO NOT EDIT.\npackage main\nvar textureIDs=map[string]uint32{\n")
	keys := make([]string, 0, len(aliases))
	for key := range aliases {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		fmt.Fprintf(&code, "%q:%d,\n", key, ids[aliases[key]])
	}
	code.WriteString("}\n")
	must(os.WriteFile("levels/room/level.toml", []byte(manifest.String()), 0644))
	must(os.WriteFile("src/textures.generated.go", []byte(code.String()), 0644))
	fmt.Printf("Imported %d atlas frames using shared Tiled package\n", len(images))
}
